import { createSpendProof, evaluateProposal } from '../sdk/index';
import type { Decision, HistoricalInput, PaymentRecord, PolicyEvaluator } from '../sdk/index';

// Fixed reviewable expectations, not generated by whichever engine CI is testing.
const expected = (code: 'APPROVED' | 'BUDGET_EXCEEDED', totalMicros: number): Decision => ({
  allowed: code === 'APPROVED', code, totalMicros, reason: 'Reviewed SDK example expectation.',
  checks: (['stopped', 'deadline', 'merchant', 'duplicate', 'budget'] as const).map(key => ({
    key, label: key, passed: !(key === 'budget' && code === 'BUDGET_EXCEEDED'), detail: 'Reviewed fixture condition.',
  })),
});
const first: PaymentRecord = {
  id: 'sdk-record-1', createdAt: '2026-09-28T12:00:00.000Z', status: 'simulated',
  quote: { id: 'sdk-quote-1', businessId: 'sdk-business-1', merchantId: 'atlas', merchantName: 'Atlas Data',
    recipient: '0x1111111111111111111111111111111111111111', item: 'Synthetic research data', amountMicros: 1_500_000, feeMicros: 100_000 },
  context: { spentMicros: 0, paidBusinessIds: [], stopped: false, now: '2026-09-28T12:00:00.000Z' },
  decision: expected('APPROVED', 1_600_000),
};
const second: PaymentRecord = {
  id: 'sdk-record-2', createdAt: '2026-09-28T12:00:01.000Z', status: 'blocked',
  quote: { ...first.quote, id: 'sdk-quote-2', businessId: 'sdk-business-2', amountMicros: 2_000_000, feeMicros: 3_000_000 },
  context: { spentMicros: 1_600_000, paidBusinessIds: ['sdk-business-1'], stopped: false, now: '2026-09-28T12:00:01.000Z' },
  decision: expected('BUDGET_EXCEEDED', 5_000_000),
};
const history: HistoricalInput = {
  policy: { budgetMicros: 5_000_000, allowedMerchants: ['atlas'], expiresAt: '2026-09-28T13:00:00.000Z', task: 'Synthetic SDK regression example' },
  records: [first, second],
};

// Deliberately broken local candidate for showing a red CI result. Never used for payment.
const omitFees: PolicyEvaluator = (quote, policy, context) => ({
  ...evaluateProposal({ ...quote, feeMicros: 0 }, policy, context),
  totalMicros: quote.amountMicros + quote.feeMicros,
});
const unsafe = process.argv.includes('--unsafe-omit-fees');
const client = createSpendProof(unsafe ? omitFees : evaluateProposal);
const boundaries = client.checkBoundaries({ quote: second.quote, policy: history.policy, context: second.context, recordId: second.id });
const regression = client.checkHistory(history);
console.log(JSON.stringify({
  engine: unsafe ? 'deliberately-broken-omit-fees' : 'current-rules',
  boundaryCases: { total: boundaries.total, failed: boundaries.failed, passed: boundaries.passed },
  historicalRecords: { total: regression.total, failed: regression.failed, passed: regression.passed },
  failedCases: boundaries.results.filter(result => !result.passed).map(result => result.kind),
  llmCalls: 0, paymentCalls: 0,
}, null, 2));
if (!boundaries.passed || !regression.passed) process.exitCode = 1;
